        } else if (configured) {
            value = configured;
        } else {
            return match;
        }
        value = String(value);
        var before = offset > 0 ? whole.charAt(offset - 1) : '';
        var after = whole.charAt(offset + match.length);
        var quoted = (before === "'" || before === '"') && after === before;
