function stageKeyForStatusName(statusName) {
    var statuses = (projectConfig && projectConfig.jira && projectConfig.jira.statuses) || {};
    var wanted = String(statusName == null ? '' : statusName).toLowerCase();
    for (var key in TAG_ONLY_STAGE_KEYS) {
        if (Object.prototype.hasOwnProperty.call(TAG_ONLY_STAGE_KEYS, key) &&
            statuses[key] === statusName) {
            return key;
        }
    }
    // gh-916 review: a project that renames the status (jira.statuses override) keeps the sm.json
    // literal targetStatus, so the configured-name lookup above misses and the fallback would never
    // apply where useConfiguredStatusesInQueries projects need it most. Second pass: the default
    // (key-derived) status name, case-insensitive.
    for (var dkey in TAG_ONLY_STAGE_KEYS) {
        if (!Object.prototype.hasOwnProperty.call(TAG_ONLY_STAGE_KEYS, dkey)) continue;
        var derived = DEFAULT_STATUSES[dkey];
        if (derived && String(derived).toLowerCase() === wanted) return dkey;
    }
    return null;
}
