+        var bug = gh916BugTicket(gh916DirectTc(tc.key, tc.status));
+        return function(args) {
+            fetchedKeys.push(args && args.key);
+            if (args && args.key === 'BUG-77') return bug;
+            return gh916FullTc(args && args.key, tc.status, tc.labels);
